Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "sender">sender</param>
/// <param name = "e">e</param>
[DataEventHandler(tableStr(PriceParameters),DataEventType::ValidatingWrite)]
public static void PriceParameters_onValidatingWrite(Common sender,DataEventArgs e)
{
    PriceParameters    priceParameters = sender;
    AVASalesParameters avaSalesParameters = AVASalesParameters::find();
    ValidateEventArgs  validateEventArgs = e as ValidateEventArgs;

    if(avaSalesParameters.PriceSearch == NoYes::No)
    {
        if(priceParameters.SalesEndAccountAll==NoYes::Yes||
            priceParameters.SalesEndAllAll==NoYes::Yes||
            priceParameters.SalesEndGroupAll==NoYes::Yes||
            priceParameters.SalesLineAccountAll==NoYes::Yes||
            priceParameters.SalesLineAccountGroup==NoYes::Yes||
            priceParameters.SalesLineAccountItem==NoYes::Yes||
            priceParameters.SalesLineAllAll==NoYes::Yes||
            priceParameters.SalesLineGroupGroup==NoYes::Yes||
            priceParameters.SalesLineAllItem==NoYes::Yes||
            priceParameters.SalesLineAllAll==NoYes::Yes||
            priceParameters.SalesLineAllGroup==NoYes::Yes||
            priceParameters.SalesLineGroupAll==NoYes::Yes||
            priceParameters.SalesLineGroupGroup==NoYes::Yes||
            priceParameters.SalesLineGroupItem==NoYes::Yes||
            priceParameters.SalesMultiLnAccountGroup==NoYes::Yes||
            priceParameters.SalesMultiLnAllAll==NoYes::Yes||
            priceParameters.SalesMultiLnAllGroup==NoYes::Yes||
            priceParameters.SalesMultiLnGroupAll==NoYes::Yes||
            priceParameters.SalesMultiLnGroupGroup==NoYes::Yes||
            priceParameters.SalesPriceAccountItem==NoYes::Yes||
            priceParameters.SalesPriceAllItem==NoYes::Yes||
            priceParameters.SalesPriceGroupItem==NoYes::Yes)
        {
            validateEventArgs.parmValidateResult(checkFailed("@NDX:NXAPriceSearchActiveError"));
        }
    }  
}
